"""Frozen Wave4 DDL; independent of future ORM edits."""
# ruff: noqa: E501

TABLES = ('actual_configurations', 'build_lots', 'sample_allocations', 'sample_units')

SCHEMA_SQL = (
    "\nCREATE TABLE actual_configurations (\n\tstatus VARCHAR(16) NOT NULL, \n\tplanned_engineering_configuration_id UUID NOT NULL, \n\tplanned_manufacturing_configuration_id UUID NOT NULL, \n\tactual_engineering_configuration_id UUID NOT NULL, \n\tactual_engineering_revision INTEGER NOT NULL, \n\tactual_manufacturing_configuration_id UUID NOT NULL, \n\tactual_manufacturing_revision INTEGER NOT NULL, \n\tobserved_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\tdifferences JSONB NOT NULL, \n\tproduct_id UUID NOT NULL, \n\tproject_id UUID NOT NULL, \n\tbuild_id UUID NOT NULL, \n\tbuild_revision INTEGER NOT NULL, \n\towner_id UUID NOT NULL, \n\tvisibility VARCHAR(16) NOT NULL, \n\trevision INTEGER NOT NULL, \n\treason TEXT NOT NULL, \n\tsources JSONB NOT NULL, \n\trequired_source_read_set JSONB NOT NULL, \n\tid UUID NOT NULL, \n\ttenant_id UUID NOT NULL, \n\tcreated_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\tPRIMARY KEY (id), \n\tUNIQUE (tenant_id, product_id, id), \n\tUNIQUE (tenant_id, product_id, project_id, build_id, id), \n\tFOREIGN KEY(tenant_id, product_id, project_id, build_id) REFERENCES builds (tenant_id, product_id, project_id, id), \n\tFOREIGN KEY(tenant_id, owner_id) REFERENCES principals (tenant_id, id), \n\tCHECK (visibility IN ('private','product') AND revision = 1 AND build_revision > 0), \n\tCHECK (status = 'recorded'), \n\tFOREIGN KEY(tenant_id, product_id, project_id, build_id, planned_engineering_configuration_id, planned_manufacturing_configuration_id) REFERENCES builds (tenant_id, product_id, project_id, id, engineering_configuration_id, manufacturing_configuration_id), \n\tFOREIGN KEY(tenant_id, product_id, planned_engineering_configuration_id, planned_manufacturing_configuration_id) REFERENCES process_revisions (tenant_id, product_id, engineering_configuration_id, id), \n\tFOREIGN KEY(tenant_id, product_id, actual_engineering_configuration_id, actual_manufacturing_configuration_id) REFERENCES process_revisions (tenant_id, product_id, engineering_configuration_id, id), \n\tFOREIGN KEY(tenant_id, product_id, actual_engineering_configuration_id, actual_engineering_revision) REFERENCES engineering_configurations (tenant_id, product_id, id, revision), \n\tFOREIGN KEY(tenant_id, product_id, actual_manufacturing_configuration_id, actual_manufacturing_revision) REFERENCES process_revisions (tenant_id, product_id, id, revision), \n\tCHECK (actual_engineering_revision > 0 AND actual_manufacturing_revision > 0), \n\tCHECK (observed_at <= created_at)\n)\n\n",
    'CREATE INDEX ix_actual_configurations_tenant_id ON actual_configurations (tenant_id)',
    "\nCREATE TABLE build_lots (\n\tstatus VARCHAR(16) NOT NULL, \n\tactual_configuration_id UUID NOT NULL, \n\tactual_configuration_revision INTEGER NOT NULL, \n\tlot_label VARCHAR(100) NOT NULL, \n\tobserved_unit_count INTEGER NOT NULL, \n\tunit VARCHAR(80) NOT NULL, \n\tobservation_system VARCHAR(100) NOT NULL, \n\tobservation_external_id VARCHAR(200) NOT NULL, \n\tobservation_nature VARCHAR(16) NOT NULL, \n\toccurred_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\treceived_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\tproduct_id UUID NOT NULL, \n\tproject_id UUID NOT NULL, \n\tbuild_id UUID NOT NULL, \n\tbuild_revision INTEGER NOT NULL, \n\towner_id UUID NOT NULL, \n\tvisibility VARCHAR(16) NOT NULL, \n\trevision INTEGER NOT NULL, \n\treason TEXT NOT NULL, \n\tsources JSONB NOT NULL, \n\trequired_source_read_set JSONB NOT NULL, \n\tid UUID NOT NULL, \n\ttenant_id UUID NOT NULL, \n\tcreated_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\tPRIMARY KEY (id), \n\tUNIQUE (tenant_id, product_id, id), \n\tUNIQUE (tenant_id, product_id, project_id, build_id, id), \n\tFOREIGN KEY(tenant_id, product_id, project_id, build_id) REFERENCES builds (tenant_id, product_id, project_id, id), \n\tFOREIGN KEY(tenant_id, owner_id) REFERENCES principals (tenant_id, id), \n\tCHECK (visibility IN ('private','product') AND revision = 1 AND build_revision > 0), \n\tCHECK (status = 'observed'), \n\tUNIQUE (tenant_id, product_id, lot_label), \n\tUNIQUE (tenant_id, product_id, observation_system, observation_external_id), \n\tUNIQUE (tenant_id, product_id, project_id, build_id, id, actual_configuration_id), \n\tFOREIGN KEY(tenant_id, product_id, project_id, build_id, actual_configuration_id) REFERENCES actual_configurations (tenant_id, product_id, project_id, build_id, id), \n\tCHECK (observed_unit_count > 0 AND actual_configuration_revision > 0), \n\tCHECK (observation_nature IN ('real','synthetic')), \n\tCHECK (occurred_at <= received_at AND received_at = created_at), \n\tCHECK (unit IN ('台','件','个','只','套','ea','piece','unit'))\n)\n\n",
    'CREATE INDEX ix_build_lots_tenant_id ON build_lots (tenant_id)',
    "\nCREATE TABLE sample_allocations (\n\tstatus VARCHAR(16) NOT NULL, \n\tlot_id UUID NOT NULL, \n\tactual_configuration_id UUID NOT NULL, \n\tunit_count INTEGER NOT NULL, \n\tproduct_id UUID NOT NULL, \n\tproject_id UUID NOT NULL, \n\tbuild_id UUID NOT NULL, \n\tbuild_revision INTEGER NOT NULL, \n\towner_id UUID NOT NULL, \n\tvisibility VARCHAR(16) NOT NULL, \n\trevision INTEGER NOT NULL, \n\treason TEXT NOT NULL, \n\tsources JSONB NOT NULL, \n\trequired_source_read_set JSONB NOT NULL, \n\tid UUID NOT NULL, \n\ttenant_id UUID NOT NULL, \n\tcreated_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\tPRIMARY KEY (id), \n\tUNIQUE (tenant_id, product_id, id), \n\tUNIQUE (tenant_id, product_id, project_id, build_id, id), \n\tFOREIGN KEY(tenant_id, product_id, project_id, build_id) REFERENCES builds (tenant_id, product_id, project_id, id), \n\tFOREIGN KEY(tenant_id, owner_id) REFERENCES principals (tenant_id, id), \n\tCHECK (visibility IN ('private','product') AND revision = 1 AND build_revision > 0), \n\tCHECK (status = 'identified'), \n\tUNIQUE (tenant_id, product_id, project_id, build_id, lot_id, id), \n\tFOREIGN KEY(tenant_id, product_id, project_id, build_id, lot_id, actual_configuration_id) REFERENCES build_lots (tenant_id, product_id, project_id, build_id, id, actual_configuration_id), \n\tCHECK (unit_count > 0 AND unit_count <= 500)\n)\n\n",
    'CREATE INDEX ix_sample_allocations_tenant_id ON sample_allocations (tenant_id)',
    "\nCREATE TABLE sample_units (\n\tstatus VARCHAR(16) NOT NULL, \n\tlot_id UUID NOT NULL, \n\tallocation_id UUID NOT NULL, \n\tactual_configuration_id UUID NOT NULL, \n\tlabel VARCHAR(100) NOT NULL, \n\toperation_key VARCHAR(80), \n\tcavity VARCHAR(100), \n\tcustodian_id UUID, \n\tcustodian_label VARCHAR(200), \n\tlocation VARCHAR(500), \n\tdestination VARCHAR(500), \n\tavailability VARCHAR(16) NOT NULL, \n\tproduct_id UUID NOT NULL, \n\tproject_id UUID NOT NULL, \n\tbuild_id UUID NOT NULL, \n\tbuild_revision INTEGER NOT NULL, \n\towner_id UUID NOT NULL, \n\tvisibility VARCHAR(16) NOT NULL, \n\trevision INTEGER NOT NULL, \n\treason TEXT NOT NULL, \n\tsources JSONB NOT NULL, \n\trequired_source_read_set JSONB NOT NULL, \n\tid UUID NOT NULL, \n\ttenant_id UUID NOT NULL, \n\tcreated_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\tPRIMARY KEY (id), \n\tUNIQUE (tenant_id, product_id, id), \n\tUNIQUE (tenant_id, product_id, project_id, build_id, id), \n\tFOREIGN KEY(tenant_id, product_id, project_id, build_id) REFERENCES builds (tenant_id, product_id, project_id, id), \n\tFOREIGN KEY(tenant_id, owner_id) REFERENCES principals (tenant_id, id), \n\tCHECK (visibility IN ('private','product') AND revision = 1 AND build_revision > 0), \n\tCHECK (status = 'identified'), \n\tUNIQUE (tenant_id, product_id, label), \n\tFOREIGN KEY(tenant_id, product_id, project_id, build_id, lot_id, allocation_id) REFERENCES sample_allocations (tenant_id, product_id, project_id, build_id, lot_id, id), \n\tFOREIGN KEY(tenant_id, product_id, project_id, build_id, lot_id, actual_configuration_id) REFERENCES build_lots (tenant_id, product_id, project_id, build_id, id, actual_configuration_id), \n\tFOREIGN KEY(tenant_id, custodian_id) REFERENCES principals (tenant_id, id), \n\tCHECK (availability IN ('unknown','hold'))\n)\n\n",
    'CREATE INDEX ix_sample_units_tenant_id ON sample_units (tenant_id)',
)
